/** Meals grouped by meal slot (stable within each slot). */
// Within each meal slot, the priority cuisine (Rajasthani) comes first.
const pri = (m: Meal) => (m.tags.includes(PRIORITY_CUISINE) ? 0 : 1);
export const MEALS: Meal[] = [...RAW].sort((a, b) => SLOT_ORDER.indexOf(a.slot) - SLOT_ORDER.indexOf(b.slot) || pri(a) - pri(b));

